import{URL,request,session,saveSession,loadCatalog,safeImage}from'./api.js';
const $=s=>document.querySelector(s);let data,revision,dirty=false,editing=-1,draft,uploading=false;const labels={heroTitle:'Título de abertura',heroSubtitle:'Complemento do título',heroDescription:'Descrição de abertura',heroButton:'Botão de abertura',collectionEyebrow:'Chamada da coleção',collectionTitle:'Título da coleção',collectionDescription:'Descrição da coleção',contactEyebrow:'Chamada de contato',contactTitle:'Título de contato',contactDescription:'Descrição de contato',footer:'Frase do rodapé',whatsapp:'WhatsApp com DDI e DDD',address:'Endereço exibido',maps:'Link do Google Maps'};
function status(text){$('#status').textContent=text}function changed(){dirty=true;$('#save').textContent='Salvar no catálogo •'}
async function init(){try{if(!session())return;const user=await request('/auth/v1/user',{auth:true});const allowed=await request('/rest/v1/catalog_editors?user_id=eq.'+encodeURIComponent(user.id)+'&select=user_id',{auth:true});if(!allowed.length){status('Seu e-mail ainda não está autorizado para editar esta loja. Solicite a liberação à responsável.');return}const row=await loadCatalog();data=structuredClone(row.content);revision=row.revision;$('#loginBox').hidden=true;$('#editor').hidden=false;$('#logout').hidden=false;fields();list();status('Tudo pronto para editar. As mudanças só aparecem para as clientes após salvar.')}catch(e){status(e.message)}}
$('#loginForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const f=new FormData(e.target);const s=await request('/auth/v1/token?grant_type=password',{method:'POST',body:{email:f.get('email'),password:f.get('password')}});saveSession(s);e.target.reset();await init()}catch(e){status('Não foi possível entrar. Confira seu e-mail e sua senha.')}finally{b.disabled=false}};
$('#logout').onclick=async()=>{if(dirty&&!confirm('Você tem alterações sem salvar. Deseja sair mesmo assim?'))return;try{await request('/auth/v1/logout',{method:'POST',auth:true})}catch{}saveSession(null);location.reload()};
function fields(){const box=$('#textFields');box.replaceChildren();Object.entries(labels).forEach(([key,label])=>{const l=document.createElement('label');l.textContent=label;const input=document.createElement(key.includes('Description')?'textarea':'input');input.value=data.texts[key]||'';input.maxLength=key==='maps'?3000:1000;input.oninput=()=>{data.texts[key]=input.value;changed()};input.dataset.field=key;l.append(input);box.append(l)});$('#heroPreview').src=safeImage(data.texts.heroImage)}
function list(){$('#modelList').replaceChildren();data.models.forEach((m,i)=>{const row=document.createElement('div');row.className='row';const img=document.createElement('img');img.src=safeImage(m.photos[0]);img.alt=m.name;const info=document.createElement('div');const name=document.createElement('strong');name.textContent=m.name;const p=document.createElement('p');p.textContent=m.colors.map(c=>c.name).join(', ')+' · '+m.sizes.join(', ');info.append(name,p);const b=document.createElement('button');b.textContent='Editar';b.onclick=()=>open(i);row.append(img,info,b);$('#modelList').append(row)});if(!data.models.length)$('#modelList').textContent='Seu catálogo ainda não tem vestidos. Clique em “Adicionar vestido” para começar.'}
function tab(models){$('#textsPanel').hidden=models;$('#modelsPanel').hidden=!models;$('#textsTab').classList.toggle('active',!models);$('#modelsTab').classList.toggle('active',models)}$('#textsTab').onclick=()=>tab(false);$('#modelsTab').onclick=()=>tab(true);
function open(i){editing=i;draft=i<0?{id:crypto.randomUUID(),name:'',desc:'',colors:[],sizes:[],photos:[]}:structuredClone(data.models[i]);$('#dialogTitle').textContent=i<0?'Adicionar vestido':'Editar vestido';$('#name').value=draft.name;$('#desc').value=draft.desc;$('#colors').value=draft.colors.map(c=>c.name).join(', ');$('#sizes').value=draft.sizes.join(', ');$('#remove').hidden=i<0;$('#modelStatus').textContent='';$('#photosInput').value='';photos();$('#modelDialog').showModal()}
$('#add').onclick=()=>open(-1);$('#close').onclick=()=>{if(!uploading)$('#modelDialog').close()};
function photos(){const box=$('#photos');box.replaceChildren();draft.photos.forEach((src,i)=>{const div=document.createElement('div');div.className='photo';const img=document.createElement('img');img.src=safeImage(src);img.alt='Foto '+(i+1);div.append(img);for(const [label,action]of[['←',()=>{if(i>0){[draft.photos[i-1],draft.photos[i]]=[draft.photos[i],draft.photos[i-1]];photos()}}],['→',()=>{if(i<draft.photos.length-1){[draft.photos[i+1],draft.photos[i]]=[draft.photos[i],draft.photos[i+1]];photos()}}],['Excluir',()=>{draft.photos.splice(i,1);photos()}]]){const b=document.createElement('button');b.type='button';b.textContent=label;b.setAttribute('aria-label',label+' foto '+(i+1));b.onclick=action;div.append(b)}box.append(div)})}
async function upload(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Use fotos em JPG, PNG ou WebP.');if(file.size>10485760)throw Error('Cada foto deve ter no máximo 10 MB.');const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type];const path=crypto.randomUUID()+'.'+ext;await request('/storage/v1/object/dresses/'+path,{method:'POST',auth:true,body:file,headers:{'Content-Type':file.type}});return URL+'/storage/v1/object/public/dresses/'+path}
$('#photosInput').onchange=async e=>{uploading=true;$('#apply').disabled=true;$('#save').disabled=true;$('#modelStatus').textContent='Enviando fotos…';try{for(const f of e.target.files){draft.photos.push(await upload(f));photos()}$('#modelStatus').textContent='Fotos enviadas. Conclua a edição e salve no catálogo.'}catch(e){$('#modelStatus').textContent=e.message}finally{uploading=false;$('#apply').disabled=false;$('#save').disabled=false;e.target.value=''}};
$('#heroUpload').onchange=async e=>{const f=e.target.files[0];if(!f)return;$('#save').disabled=true;status('Enviando imagem…');try{data.texts.heroImage=await upload(f);$('#heroPreview').src=data.texts.heroImage;changed();status('Imagem enviada. Clique em Salvar no catálogo para publicar.')}catch(e){status(e.message)}finally{$('#save').disabled=false;e.target.value=''}};
const split=s=>[...new Set(s.split(',').map(x=>x.trim()).filter(Boolean))];$('#modelForm').onsubmit=e=>{e.preventDefault();if(uploading)return;const colors=split($('#colors').value),sizes=split($('#sizes').value);if(!draft.photos.length||!colors.length||!sizes.length){$('#modelStatus').textContent='Adicione pelo menos uma foto, uma cor e um tamanho.';return}draft.name=$('#name').value.trim();if(!draft.name)return;draft.desc=$('#desc').value.trim();draft.colors=colors.map(name=>({name,hex:draft.colors.find(c=>c.name===name)?.hex||'#49614e'}));draft.sizes=sizes;if(editing<0)data.models.push(draft);else data.models[editing]=draft;list();changed();$('#modelDialog').close();status('Vestido atualizado no painel. Clique em Salvar no catálogo para publicar.')};
$('#remove').onclick=()=>{if(confirm('Remover este vestido do catálogo? A mudança será publicada quando você salvar.')){data.models.splice(editing,1);changed();list();$('#modelDialog').close()}};
$('#save').onclick=async()=>{const b=$('#save');b.disabled=true;try{const num=data.texts.whatsapp.replace(/\D/g,'');if(!/^\d{10,15}$/.test(num))throw Error('Confira o WhatsApp, incluindo DDI e DDD.');if(!data.texts.heroTitle.trim()||!data.texts.collectionTitle.trim())throw Error('Preencha o título inicial e o título da coleção.');const maps=new window.URL(data.texts.maps);if(maps.protocol!=='https:')throw Error('Use um link seguro do Google Maps.');status('Salvando alterações…');const rows=await request('/rest/v1/catalog?id=eq.1&revision=eq.'+revision,{method:'PATCH',auth:true,headers:{Prefer:'return=representation'},body:{content:data,revision:revision+1,updated_at:new Date().toISOString()}});if(!rows?.length)throw Error('Outra pessoa alterou o catálogo. Copie suas mudanças e atualize a página antes de salvar novamente.');revision=rows[0].revision;dirty=false;b.textContent='Salvar no catálogo';status('Salvo! As alterações já estão no catálogo. Se ele estiver aberto, atualiza em até 10 segundos.')}catch(e){status('Não foi possível salvar: '+e.message)}finally{b.disabled=false}};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});init();
